
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_pi_m06_2x_dl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_pi_m06_2x_dl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.994132621123740e-02, -6.904245552385017e-02, -6.774337232288218e-02, -6.586383223789390e-02, -6.314369246591066e-02, -5.921777937436815e-02, -5.361846573127238e-02, -4.592033645262317e-02, -3.628463910981387e-02, -2.590479963405986e-02, -1.739014026692384e-02, -3.690270878877486e-02, -4.608058399691813e-02, -2.949746722429971e-02, -1.390390859052017e-02, -1.790006297366323e-03, 3.298131691506467e-04, -4.596245069017511e-04, -1.080553709949450e-04, -8.658662005177978e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


